// Generates README.md and gallery/*.md from data/list.yml, screenshots and refs/.
//   node scripts/build.mjs          write files
//   node scripts/build.mjs --check  exit 1 if generated files are out of date
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import {
  ROOT, GALLERY_DIR, BOARD_DIR, REFS_DIR, IMAGE_EXT, VIDEO_EXT, TAG_EMOJI,
  loadData, slugify, itemSlug, slugForUrl, shotFile, thumbFile, exists, folderRefs, titleFromFile,
} from './lib.mjs';

const CHECK = process.argv.includes('--check');
const COLS = 3;

const esc = (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const tags = (item) => (item.tags || []).map((t) => TAG_EMOJI[t] || '').join('');
const ghAnchor = (heading) => heading.toLowerCase().trim().replace(/[^\p{L}\p{N} _-]/gu, '').replace(/ /g, '-');
const rel = (from, abs) => path.relative(from, abs).split(path.sep).join('/');

function readTemplate(name) {
  return fs.readFileSync(path.join(ROOT, 'templates', name), 'utf8').trim();
}

// Best image to show for an item, relative to `fromDir`.
function thumbFor(item, fromDir) {
  if (item.noshot) return null;
  const slug = itemSlug(item);
  if (exists(thumbFile(slug))) return rel(fromDir, thumbFile(slug));
  if (exists(shotFile(slug))) return rel(fromDir, shotFile(slug));
  return null;
}

function nameLinks(item) {
  const main = `<a href="${esc(item.url)}">${esc(item.name.split(' / ')[0])}</a>`;
  const also = (item.also || []).map((a) => `<a href="${esc(a.url)}">${esc(a.name)}</a>`);
  return [main, ...also].join(' / ');
}

function card(item, sectionSlug) {
  const slug = itemSlug(item);
  const galleryLink = `gallery/${sectionSlug}.md#${slug}`;
  const img = thumbFor(item, ROOT);
  const refCount = allRefs(item).length;
  const lines = [];
  if (img) lines.push(`<a href="${galleryLink}"><img src="${img}" alt="${esc(item.name)} screenshot" width="100%"></a><br>`);
  lines.push(`<b>${nameLinks(item)}</b> ${tags(item)}<br>`);
  lines.push(`<sub>${esc(item.desc)}</sub>`);
  if (img || refCount) lines.push(`<br><sub><a href="${galleryLink}">🖼️ ${refCount ? `${refCount + (img ? 1 : 0)} references` : 'View larger'}</a></sub>`);
  return lines.join('\n');
}

function grid(cells, cols = COLS) {
  if (!cells.length) return '';
  const width = Math.floor(100 / cols);
  const rows = [];
  for (let i = 0; i < cells.length; i += cols) {
    const tds = cells.slice(i, i + cols).map((c) => `<td width="${width}%" valign="top">\n${c}\n</td>`);
    rows.push(`<tr>\n${tds.join('\n')}\n</tr>`);
  }
  return `<table>\n${rows.join('\n')}\n</table>`;
}

function allRefs(item) {
  const declared = item.refs || [];
  const declaredFiles = new Set(declared.filter((r) => r.file).map((r) => r.file));
  const dropped = folderRefs(itemSlug(item)).filter((r) => !declaredFiles.has(r.file));
  return [...declared, ...dropped];
}

function refMedia(ref, fromDir) {
  const title = esc(ref.title || ref.url || ref.link || ref.file);
  if (ref.url) {
    const slug = slugForUrl(ref.url);
    const img = exists(shotFile(slug)) ? rel(fromDir, shotFile(slug)) : null;
    return img
      ? `<a href="${esc(ref.url)}"><img src="${img}" alt="${title}" width="100%"></a><br><sub><a href="${esc(ref.url)}">${title}</a></sub>`
      : `<sub>📷 <a href="${esc(ref.url)}">${title}</a> <i>(screenshot pending)</i></sub>`;
  }
  if (ref.file) {
    const abs = path.join(REFS_DIR, ref.file);
    if (!exists(abs)) return `<sub>⚠️ missing file <code>refs/${esc(ref.file)}</code></sub>`;
    const src = rel(fromDir, abs);
    const ext = path.extname(ref.file).toLowerCase();
    const caption = ref.source ? `<a href="${esc(ref.source)}">${title}</a>` : title;
    if (VIDEO_EXT.includes(ext)) return `<sub>🎬 <a href="${src}">${title}</a> (video)</sub>`;
    return `<a href="${src}"><img src="${src}" alt="${title}" width="100%"></a><br><sub>${caption}</sub>`;
  }
  if (ref.link) return `<sub>🔗 <a href="${esc(ref.link)}">${title}</a></sub>`;
  return '';
}

function galleryPage(section, sectionSlug) {
  const out = [`# ${section.title} — Gallery`, '', `[← Back to list](../README.md#${ghAnchor(section.title)}) · [All galleries](README.md)`, ''];
  for (const group of section.groups) {
    if (group.title) out.push(`## ${group.title}`, '');
    for (const item of group.items) {
      const slug = itemSlug(item);
      out.push(`<a id="${slug}"></a>`, '', `### [${item.name.split(' / ')[0]}](${item.url}) ${tags(item)}`.trim(), '', item.desc, '');
      if (!item.noshot) {
        const img = exists(shotFile(slug)) ? rel(GALLERY_DIR, shotFile(slug)) : null;
        out.push(img ? `<a href="${item.shot || item.url}"><img src="${img}" alt="${esc(item.name)} screenshot" width="100%"></a>` : '_Screenshot pending — generated by the next capture run._', '');
      }
      const refs = allRefs(item);
      if (refs.length) out.push('**More references**', '', grid(refs.map((r) => refMedia(r, GALLERY_DIR)), 2), '');
      out.push(`<sub>Add a reference: drop images into <code>refs/${slug}/</code> or add <code>refs:</code> to this entry in <code>data/list.yml</code>.</sub>`, '', '---', '');
    }
  }
  return out.join('\n').trim() + '\n';
}

function boardPage() {
  const out = ['# Reference Board', '', 'Anything worth referencing that is not tied to one library: layouts, interactions, animations, colour palettes, typography, real product screens.', '', '[← Back to list](../README.md) · [All galleries](README.md)', ''];
  let captions = {};
  const capFile = path.join(BOARD_DIR, 'captions.yml');
  if (exists(capFile)) captions = YAML.parse(fs.readFileSync(capFile, 'utf8')) || {};
  const groups = new Map();
  const walk = (dir, group) => {
    if (!exists(dir)) return;
    for (const f of fs.readdirSync(dir).sort()) {
      const abs = path.join(dir, f);
      if (f.startsWith('.')) continue;
      if (fs.statSync(abs).isDirectory()) { walk(abs, titleFromFile(f)); continue; }
      const ext = path.extname(f).toLowerCase();
      if (![...IMAGE_EXT, ...VIDEO_EXT].includes(ext)) continue;
      const key = rel(BOARD_DIR, abs);
      const c = captions[key] || {};
      if (!groups.has(group)) groups.set(group, []);
      groups.get(group).push(refMedia({ file: rel(REFS_DIR, abs), title: c.title || titleFromFile(f), source: c.source }, GALLERY_DIR));
    }
  };
  walk(BOARD_DIR, 'General');
  if (!groups.size) out.push('_Nothing here yet — add the first reference! See [CONTRIBUTING.md](../CONTRIBUTING.md#reference-board)._', '');
  for (const [g, cells] of groups) out.push(`## ${g}`, '', grid(cells), '');
  return out.join('\n').trim() + '\n';
}

function build() {
  const data = loadData();
  const files = new Map();

  const toc = ['## Contents', '', '- [Quick Stack Recipes](#quick-stack-recipes)'];
  const body = [];
  const galleryIndex = ['# Gallery', '', 'Full-size screenshots and extra references for every entry.', '', '[← Back to list](../README.md)', ''];
  let total = 0; let withShots = 0;

  for (const section of data.sections) {
    const sectionSlug = slugify(section.title);
    toc.push(`- [${section.title}](#${ghAnchor(section.title)})`);
    body.push('---', '', `## ${section.title}`, '');
    if (section.intro) body.push(section.intro, '');
    let count = 0;
    for (const group of section.groups) {
      if (group.title) {
        toc.push(`  - [${group.title}](#${ghAnchor(group.title)})`);
        body.push(`### ${group.title}`, '');
      }
      if (group.intro) body.push(group.intro, '');
      body.push(grid(group.items.map((it) => card(it, sectionSlug))), '');
      for (const it of group.items) { count++; total++; if (thumbFor(it, ROOT)) withShots++; }
    }
    body.push(`<sub>[🖼️ Open the ${section.title} gallery](gallery/${sectionSlug}.md)</sub>`, '');
    files.set(path.join(GALLERY_DIR, `${sectionSlug}.md`), galleryPage(section, sectionSlug));
    galleryIndex.push(`- [${section.title}](${sectionSlug}.md) — ${count} entries`);
  }
  galleryIndex.push('', '- [Reference Board](board.md) — community references not tied to one library');
  toc.push('- [Contributing](#contributing)');

  const stats = `<sub>${total} entries · ${withShots} with screenshots · generated from <code>data/list.yml</code></sub>`;
  const readme = [readTemplate('header.md'), '', toc.join('\n'), '', stats, '', body.join('\n').trim(), '', '---', '', readTemplate('footer.md'), ''].join('\n');

  files.set(path.join(ROOT, 'README.md'), readme);
  files.set(path.join(GALLERY_DIR, 'README.md'), galleryIndex.join('\n') + '\n');
  files.set(path.join(GALLERY_DIR, 'board.md'), boardPage());
  return { files, total, withShots };
}

const { files, total, withShots } = build();
let stale = 0;
for (const [file, content] of files) {
  const current = exists(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === content) continue;
  stale++;
  if (CHECK) { console.error(`out of date: ${path.relative(ROOT, file)}`); continue; }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  console.log(`wrote ${path.relative(ROOT, file)}`);
}
console.log(`${total} entries, ${withShots} with screenshots`);
if (CHECK && stale) { console.error('\nRun `npm run build` and commit the result.'); process.exit(1); }
